// src/components/KnowYourCandidate.js
import React, { useState, useEffect, useRef } from "react";

const KnowYourCandidate = ({ language }) => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const chatEndRef = useRef(null);

  const t = {
    hindi: {
      title: "अपने उम्मीदवार को जानें 🤖",
      placeholder: "यहाँ टाइप करें जैसे — वाराणसी के लोकसभा उम्मीदवार कौन हैं?",
      send: "भेजें",
      loading: "डेटा लोड हो रहा है...",
      intro:
        "आप यहाँ अपने क्षेत्र के उम्मीदवारों के बारे में पूछ सकते हैं। उदाहरण: 'कानपुर के 2024 लोकसभा उम्मीदवार कौन हैं?'",
      errorNoData: "माफ़ करें, इस क्षेत्र के लिए जानकारी नहीं मिल सकी।",
    },
    english: {
      title: "Know Your Candidate 🤖",
      placeholder:
        "Type here, e.g. Who are the 2024 Lok Sabha candidates from Varanasi?",
      send: "Send",
      loading: "Loading data...",
      intro:
        "Ask about candidates for your area. Example: 'Who are the 2024 candidates from Lucknow?'",
      errorNoData: "Sorry, no information found for this area.",
    },
  }[language || "english"];

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = { role: "user", text: input };
    setMessages((prev) => [...prev, userMessage]);
    setInput("");
    setLoading(true);

    try {
      // call backend API
      const response = await fetch("/api/getCandidates", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: input }),
      });

      const result = await response.json();

      if (!response.ok || !result.data) {
        const aiMessage = {
          role: "assistant",
          text: t.errorNoData,
        };
        setMessages((prev) => [...prev, aiMessage]);
      } else {
        const aiMessage = {
          role: "assistant",
          text: result.data,
        };
        setMessages((prev) => [...prev, aiMessage]);
      }
    } catch (error) {
      const aiMessage = {
        role: "assistant",
        text:
          language === "hindi"
            ? "माफ़ करें, सेवा अस्थायी रूप से उपलब्ध नहीं है।"
            : "Sorry, the service is temporarily unavailable.",
      };
      setMessages((prev) => [...prev, aiMessage]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter" && !loading) sendMessage();
  };

  return (
    <div className="ai-chat-container">
      <div className="chat-header">
        <h2>{t.title}</h2>
        <p className="chat-intro">{t.intro}</p>
      </div>

      <div className="chat-box">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`chat-message ${
              msg.role === "user" ? "user-msg" : "ai-msg"
            }`}
          >
            <div className="message-bubble">
              {msg.role === "assistant" && <span className="ai-icon">🤖</span>}
              <p>{msg.text}</p>
            </div>
          </div>
        ))}

        {loading && (
          <div className="chat-message ai-msg">
            <div className="message-bubble loading-bubble">
              <span className="ai-icon">🤖</span> {t.loading}
            </div>
          </div>
        )}

        <div ref={chatEndRef} />
      </div>

      <div className="chat-input-section">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={t.placeholder}
          disabled={loading}
        />
        <button onClick={sendMessage} disabled={loading}>
          {t.send}
        </button>
      </div>
    </div>
  );
};

export default KnowYourCandidate;
